    siz = _siz;
    sum.resize(_siz);
  }
  void update(int x, T d) {
    for (int i = x; i < siz; i = i | (i + 1)) sum[i] += d;
  }
  T query(int x) {
    T ret = 0;
    for (int i = x; i >= 0; i = (i & (i + 1)) - 1) ret += sum[i];
