struct BIT {
  int sz;
  int t[N];
  void init() {
    sz = m + 1;
    for (int i = (0); i <= (sz); ++i) t[i] = 0;
  }
  int lowbit(int x) { return x & (-x); }
  void upd(int x, int v) {
    while (x <= sz) t[x] += v, x += lowbit(x);
  }
  int qry(int x) {
    int ret = 0;
    while (x) ret += t[x], x -= lowbit(x);
    return ret;
  }
} tr[N];
