def __getprimes(n):
    isprime = [True for i in range(n + 1)]
    primes = []

    for i in range(2, n + 1):
        if isprime[i]:
            for j in range(i * i, n + 1, i):
                isprime[j] = False
    for i in range(2, n + 1):
        if isprime[i]:
