void init() {
  fac.resize(sz, 1);
  ifac.resize(sz);
  for (long long i = 2; i < sz; i++) fac[i] = (fac[i - 1] * i) % mod;
  ifac[sz - 1] = mpow(fac[sz - 1]);
  for (long long i = sz - 2; i >= 0; i--)
    ifac[i] = (ifac[i + 1] * (i + 1)) % mod;
  prime.resize(sz);
  for (int i = 2; i < sz; i++) prime[i] = i;
  for (long long i = 2; i * i < sz; i++) {
