  s[p].pl = s[p << 1].pl;
  s[p].pr = s[p << 1 | 1].pr;
  s[p].len = s[p << 1].len + s[p << 1 | 1].len;
  s[p].ans = s[p << 1].ans + s[p << 1 | 1].ans;
  if (s[p << 1].ll == s[p << 1].len) {
    if (s[p << 1].pr <= s[p << 1 | 1].pl) {
      s[p].ll = s[p << 1].ll + s[p << 1 | 1].ll;
    } else {
      s[p].ll = s[p << 1].ll;
    }
  } else {
    s[p].ll = s[p << 1].ll;
  }
  if (s[p << 1 | 1].lr == s[p << 1 | 1].len) {
    if (s[p << 1].pr <= s[p << 1 | 1].pl) {
      s[p].lr = s[p << 1].lr + s[p << 1 | 1].lr;
    } else {
      s[p].lr = s[p << 1 | 1].lr;
    }
  } else {
    s[p].lr = s[p << 1 | 1].lr;
  }
  if (s[p << 1 | 1].pl >= s[p << 1].pr) {
    s[p].ans += s[p << 1 | 1].ll * s[p << 1].lr;
  }
}
void modify(long long p, long long l, long long r, long long x, long long v) {
  if (l == r) {
    s[p].l = x;
    s[p].pl = s[p].pr = v;
    s[p].ll = s[p].lr = 1;
    s[p].ans = 1;
    s[p].len = 1;
    return;
  }
  long long mid = (l + r) >> 1;
  if (x <= mid) {
    modify(p << 1, l, mid, x, v);
  } else {
    modify(p << 1 | 1, mid + 1, r, x, v);
  }
  up(p);
}
sgm_tree hb(sgm_tree a, sgm_tree b) {
  sgm_tree res;
  res.pl = a.pl;
  res.pr = b.pr;
  res.len = a.len + b.len;
  res.ans = a.ans + b.ans;
  if (a.ll == a.len) {
    if (a.pr <= b.pl) {
      res.ll = a.ll + b.ll;
    } else {
      res.ll = a.ll;
    }
  } else {
    res.ll = a.ll;
  }
  if (b.lr == b.len) {
    if (a.pr <= b.pl) {
      res.lr = a.lr + b.lr;
    } else {
      res.lr = b.lr;
    }
  } else {
    res.lr = b.lr;
  }
  if (b.pl >= a.pr) {
    res.ans += b.ll * a.lr;
  }
  return res;
}
vector<sgm_tree> v;
void query(long long p, long long l, long long r, long long x, long long y) {
  if (x <= l && y >= r) {
    v.push_back(s[p]);
    return;
  }
  long long mid = (l + r) >> 1;
  if (x <= mid) {
    query(p << 1, l, mid, x, y);
  }
  if (y > mid) {
    query(p << 1 | 1, mid + 1, r, x, y);
  }
}
long long js() {
  sort(v.begin(), v.end());
  sgm_tree res;
  if (v.size() == 1) {
    res = v[0];
    return res.ans;
  } else {
    res = hb(v[0], v[1]);
  }
  for (long long i = 2; i < v.size(); i++) {
    res = hb(res, v[i]);
  }
  return res.ans;
}
void print(long long x) {
  if (x >= 10) print(x / 10);
  putchar(x % 10 + '0');
}
signed main() {
  long long n = read(), q = read();
  for (long long i = 1; i <= n; i++) {
    long long fz = read();
    modify(1, 1, n, i, fz);
  }
  while (q--) {
    long long t = read(), x = read(), y = read();
    if (t == 1) {
      modify(1, 1, n, x, y);
    } else {
      query(1, 1, n, x, y);
      long long ans = js();
      v.clear();
      print(ans);
      putchar('\n');
    }
  }
  return 0;
}
#include <bits/stdc++.h>
using namespace std;
const int mod = 1000000007;
long long n, q, v[200002];
long long aintL[800002], aintR[800002];
long long cnt[800002];
void build(int nod, int st, int dr) {
  if (st == dr) {
    aintL[nod] = aintR[nod] = cnt[nod] = 1;
    return;
  }
  int mid = (st + dr) / 2;
  build(nod << 1, st, mid);
  build(nod << 1 | 1, mid + 1, dr);
  cnt[nod] = cnt[nod << 1] + cnt[nod << 1 | 1];
  aintL[nod] = aintL[nod << 1];
  aintR[nod] = aintR[nod << 1 | 1];
  if (aintL[nod << 1] == mid - st + 1 && v[mid] <= v[mid + 1])
    aintL[nod] += aintL[nod << 1 | 1];
  if (aintR[nod << 1 | 1] == dr - mid && v[mid] <= v[mid + 1])
    aintR[nod] += aintR[nod << 1];
  if (v[mid] <= v[mid + 1])
    cnt[nod] += 1LL * aintR[nod << 1] * aintL[nod << 1 | 1];
}
void update(int nod, int st, int dr, int poz, int val) {
  if (st == dr) {
    aintL[nod] = aintR[nod] = cnt[nod] = 1;
    return;
  }
  int mid = (st + dr) / 2;
  if (poz <= mid)
    update(nod << 1, st, mid, poz, val);
  else
    update(nod << 1 | 1, mid + 1, dr, poz, val);
  cnt[nod] = cnt[nod << 1] + cnt[nod << 1 | 1];
  aintL[nod] = aintL[nod << 1];
  aintR[nod] = aintR[nod << 1 | 1];
  if (aintL[nod << 1] == mid - st + 1 && v[mid] <= v[mid + 1])
    aintL[nod] += aintL[nod << 1 | 1];
  if (aintR[nod << 1 | 1] == dr - mid && v[mid] <= v[mid + 1])
    aintR[nod] += aintR[nod << 1];
  if (v[mid] <= v[mid + 1])
    cnt[nod] += 1LL * aintR[nod << 1] * aintL[nod << 1 | 1];
}
long long ans = 0;
long long strk = 0;
void query(int nod, int st, int dr, int L, int R) {
  if (dr < L || st > R) return;
  if (L <= st && dr <= R) {
    ans += cnt[nod];
    if (strk != 0) {
      if (v[st - 1] <= v[st]) {
        ans += strk * aintL[nod];
        if (aintL[nod] == dr - st + 1)
          strk += dr - st + 1;
        else
          strk = aintR[nod];
      } else
        strk = aintR[nod];
    } else
      strk = aintR[nod];
    return;
  }
  int mid = (st + dr) / 2;
  query(nod << 1, st, mid, L, R);
  query(nod << 1 | 1, mid + 1, dr, L, R);
}
int main() {
  cin >> n >> q;
  for (int i = 1; i <= n; ++i) cin >> v[i];
  build(1, 1, n);
  for (; q; --q) {
    int tip;
    cin >> tip;
    if (tip == 1) {
      int poz, val;
      cin >> poz >> val;
      v[poz] = val;
      update(1, 1, n, poz, val);
    } else {
      int L, R;
      cin >> L >> R;
      ans = 0;
      strk = 0;
      query(1, 1, n, L, R);
      cout << ans << '\n';
    }
  }
  return 0;
}
